        if seen < 2:
            continue
        pieces = {piece.strip() for answer in answers if char in answer
                  for piece in answer.split(char) if piece.strip()}
        if len(pieces) < 2:
            continue
        reuse = sum(1 for piece in pieces if piece in whole) / len(pieces)
        if reuse < min_reuse:
